/* @autogenerated */
import { TestBed, fakeAsync, tick } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { OAuthService, provideOAuthClient } from 'angular-oauth2-oidc';

// Usa el OAuthService real con la misma configuración de refresco que OidcIdentityHandlerService
// (useSilentRefresh: false, timeoutFactor: 0.75, setupAutomaticSilentRefresh({}, 'access_token')).
const TOKEN_ENDPOINT = 'https://idp.example.com/token';
const ACCESS_TTL = 120_000; // access token de 2 minutos
const ID_TTL = 90_000; // id token con otra vida: su temporizador no debe provocar otro refresco

describe('OIDC token refresh (real OAuthService)', () => {
  let oauth: OAuthService;
  let backend: HttpTestingController;

  const storeTokens = () => {
    const now = Date.now();
    sessionStorage.setItem('access_token', 'access-1');
    sessionStorage.setItem('access_token_stored_at', String(now));
    sessionStorage.setItem('expires_at', String(now + ACCESS_TTL));
    sessionStorage.setItem('refresh_token', 'refresh-1');
    sessionStorage.setItem('id_token', 'id-1');
    sessionStorage.setItem('id_token_stored_at', String(now));
    sessionStorage.setItem('id_token_expires_at', String(now + ID_TTL));
  };

  const refreshRequests = () => backend.match((req) => req.method === 'POST' && req.url === TOKEN_ENDPOINT);

  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting(), provideOAuthClient()],
    });
    oauth = TestBed.inject(OAuthService);
    backend = TestBed.inject(HttpTestingController);
    oauth.setStorage(sessionStorage);
  });

  afterEach(() => sessionStorage.clear());

  it('sends exactly one refresh request per access token expiry', fakeAsync(() => {
    storeTokens();
    oauth.configure({
      responseType: 'code',
      tokenEndpoint: TOKEN_ENDPOINT,
      clientId: 'phylax-ui',
      scope: 'openid offline_access',
      oidc: true,
      requireHttps: false,
      useSilentRefresh: false,
      timeoutFactor: 0.75,
    });
    oauth.setupAutomaticSilentRefresh({}, 'access_token');

    // El temporizador del id token (75% de 90 s) salta antes y no refresca
    tick(ID_TTL * 0.75 + 2_000);
    expect(refreshRequests().length).toBe(0);

    // 75% de 120 s + 1 s de debounce: una sola petición
    tick(ACCESS_TTL * 0.75 - ID_TTL * 0.75);
    const first = refreshRequests();
    expect(first.length).toBe(1);
    expect(first[0].request.body.toString()).toContain('grant_type=refresh_token');
    first[0].flush({ access_token: 'access-2', refresh_token: 'refresh-2', expires_in: ACCESS_TTL / 1000 });
    expect(oauth.getAccessToken()).toBe('access-2');

    // Ciclo siguiente con el token renovado: otra única petición
    tick(ACCESS_TTL * 0.75 + 1_000);
    const second = refreshRequests();
    expect(second.length).toBe(1);
    second[0].flush({ access_token: 'access-3', refresh_token: 'refresh-3', expires_in: ACCESS_TTL / 1000 });

    oauth.stopAutomaticRefresh();
    backend.verify();
  }));
});
